namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, CapCents);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
EOF
cat > $D/PromoCodePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int DiscountCents(string? code, int subtotalCents, int loyaltyDiscountCents) =>
        code?.ToUpperInvariant() switch
        {
            "WELCOME5" => WelcomeFiveCents,
            "SUMMER10" => Math.Min((subtotalCents - loyaltyDiscountCents) / 10, SummerTenCapCents),
            _ => 0
        };
}
EOF
cat > $D/DiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier);
        var promoCents = PromoCodePolicy.DiscountCents(promoCode, subtotalCents, loyaltyCents);
        return Math.Min(subtotalCents, loyaltyCents + promoCents);
    }
}
EOF
