public CheckoutQuote Handle(QuoteCheckoutQuery query)
{
    var payableCents = new CalculateLoyaltyDiscount()
        .Handle(new CalculateLoyaltyDiscountQuery(query.SubtotalCents, query.LoyaltyTier, query.PromoCode))
        .TotalCents;
    var shippingCents = new CalculateShippingFee()
        .Handle(new CalculateShippingFeeQuery(payableCents, query.LoyaltyTier, query.Express));
    return new(payableCents, shippingCents, payableCents + shippingCents);
}

