+namespace CheckoutPricing.Domain;
+
+public static class DiscountPolicy
+{
+    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
+    {
+        var loyaltyCents = LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier);
+        var promoCents = PromoCodePolicy.DiscountCents(promoCode, subtotalCents, loyaltyCents);
+        return Math.Min(subtotalCents, loyaltyCents + promoCents);
+    }
+}

